recs=[]
recs.append(R(9477520,"روسٹ کی ہوئی لال شملہ مرچ اور ٹماٹر کا سوپ",
"ناقابلِ یقین حد تک ذائقے دار روسٹ کی ہوئی لال شملہ مرچ اور ٹماٹر کا سوپ! یہ کریمی، تازہ، گرمائش بخش اور مکمل طور پر خوشبودار ہے۔",
"4 سرونگ","1 سرونگ",
["3 لال شملہ مرچیں چار حصوں میں کٹی ہوئی","1 پاؤنڈ بیل پر پکے ہوئے ٹماٹر یا پلم ٹماٹر چار حصوں میں کٹے ہوئے (تقریباً 5-7 پلم ٹماٹر)","1 پیلی پیاز چار حصوں میں کٹی ہوئی","4 بڑے جوے لہسن، چھیلیں نہیں","1 کھانے کا چمچ ایووکاڈو کا تیل، اختیاری، *بغیر تیل کے لیے چھوڑ دیں اور اس کی جگہ شوربہ استعمال کریں","½ چائے کا چمچ خشک اجمود","½ چائے کا چمچ خشک تلسی","3 کپ کم سوڈیم سبزیوں کا شوربہ","¼ کپ کچے کاجو","حسبِ ذائقہ نمک اور کالی مرچ",
("اختیاری سجاوٹ","تازہ تلسی یا اجمود"),("اختیاری سجاوٹ","کروٹونز")],
["اوون کو 425 ڈگری F پر کنویکشن بیک پر پہلے سے گرم کریں، اور ایک بڑی بیکنگ شیٹ پر پارچمنٹ پیپر بچھا لیں۔ اپنی سبزیاں ایک تہہ میں رکھیں اور اوپر تیل (اگر استعمال کر رہے ہیں) ڈالیں اور اجمود اور تلسی چھڑکیں۔",
"سبزیوں کو 30-40 منٹ روسٹ کریں، یا مرچوں کے چھلکے کچھ کالے ہونے تک، پھر اوون سے نکال لیں۔ ہاتھ لگانے کے قابل ٹھنڈی ہونے پر مرچیں چھیل لیں۔ (چھلکے آسانی سے اتر جائیں گے، لیکن اگر کوئی ضدی ٹکڑے ہوں تو انہیں رہنے دیں۔)",
"لہسن چھیلیں، روسٹ ہونے کے بعد وہ بہت آسانی سے نکل آئیں گے، اور اپنے بلینڈر میں سجاوٹ کے سوا باقی تمام اجزا کے ساتھ ڈالیں۔ ہموار ہونے تک بلینڈ کریں، نمک اور کالی مرچ چکھیں اور ضرورت ہو تو ٹھیک کریں۔",
"تازہ تلسی، کروٹونز، کریکرز یا کالی مرچ سے سجا کر پیش کریں۔"],
["بغیر تیل کے لیے سبزیوں پر تیل کی جگہ شوربہ ڈالیں لیکن انہیں اکثر دیکھتے رہنا اور ضرورت ہو تو مزید پانی یا شوربہ ڈالنا یقینی بنائیں۔ روسٹ کرنے سے پہلے اپنا لہسن نہ چھیلیں ورنہ آپ کا لہسن جل سکتا ہے۔ روسٹ ہونے کے بعد چھلکا بہت آسانی سے اتر جائے گا۔ بہترین نتائج کے لیے تازہ، پکے ہوئے ٹماٹر استعمال کریں۔ ڈبہ بند یا جار والے یہاں اچھا کام نہیں کریں گے۔ یقینی بنائیں کہ مرچوں کے چھلکے اچھی طرح کالے ہوں تاکہ چھلکے آسانی سے اتر جائیں۔ اگر چھیلنے میں مشکل ہو رہی ہو تو روسٹ کرنے کے بعد انہیں ایک پیالے میں رکھ کر اوپر تولیہ ڈال کر بھاپ دے سکتے ہیں۔ اگر آپ کے پاس تیز رفتار بلینڈر ہے اور آپ کی سبزیاں ٹھنڈی ہو گئی ہیں تو سوپ کو مزید گرم کرنے کے لیے چند اضافی منٹ بلینڈ کریں۔ اگر آپ کے پاس تیز رفتار بلینڈر نہیں ہے تو اپنے بلینڈر میں ڈالنے سے پہلے کاجو کو ابلتے ہوئے گرم پانی میں 20-30 منٹ بھگو کر چھان لیں۔ (آپ یہ سبزیوں کے روسٹ ہوتے وقت کر سکتے ہیں۔) بچا ہوا فریج میں 4 دن تک رہتا ہے، یا فریزر کے لیے موزوں ہوا بند ڈبے میں 3 ماہ تک منجمد کریں۔"],[]))
recs.append(R(9479544,"انسٹنٹ پاٹ میشڈ پوٹیٹوز، پانی نکالنے کی ضرورت نہیں!",
"اس سے آسان نہیں ہو سکتا! انسٹنٹ پاٹ میشڈ پوٹیٹوز فوراً تیار ہو جاتے ہیں، پانی نکالنے کی ضرورت نہیں۔ ہر بار بہترین آلو کے لیے 1 برتن میں پکائیں اور میش کریں!",
"6 سرونگ","1 سرونگ",
["3 پاؤنڈ یوکون گولڈ آلو یا پیلے آلو","1 کپ کم سوڈیم سبزیوں کا شوربہ","⅓ کپ سویا دودھ یا آپ کی پسند کا","1 چائے کا چمچ سمندری نمک","½ چائے کا چمچ لہسن پاؤڈر، اختیاری","1-2 کھانے کے چمچ ویگن مکھن یا مارجرین، اختیاری",
("اختیاری سجاوٹ","تازہ چائیوز"),("اختیاری سجاوٹ","تازہ روزمیری"),("اختیاری سجاوٹ","پگھلا ہوا مکھن"),("اختیاری سجاوٹ","پیاز کی گریوی")],
["آلو چھیل کر ایک انچ کے ٹکڑوں میں کاٹیں۔ انہیں شوربے کے ساتھ اپنے برتن میں رکھیں اور ڈھکن بند کریں، والو کو سیلنگ کی پوزیشن پر رکھ دیں۔ 6 منٹ کے لیے ہائی پریشر پر سیٹ کریں۔ (پریشر تک پہنچنے میں تقریباً 10 منٹ لگیں گے، اور پھر ٹائمر الٹی گنتی شروع کرے گا۔) ٹائمر مکمل ہونے پر پریشر کوئیک ریلیز کریں اور محفوظ ہونے پر ڈھکن کھولیں۔",
"دودھ، نمک اور کوئی بھی اختیاری اجزا ڈالیں۔ پھر آلو میشر سے ہموار اور کریمی ہونے تک میش کریں۔ چکھیں اور ضرورت ہو تو مزید نمک ڈالیں، پھر گرم پیش کریں۔"],
["*یہ ترکیب جیسی لکھی ہے 6qt انسٹنٹ پاٹ ماڈل کے لیے ہے۔ اگر آپ 8qt ماڈل استعمال کر رہے ہیں تو شوربہ 1.5 کپ کر دیں۔ اگر آلو دگنے کر رہے ہیں تو شوربہ دگنا کرنے کی ضرورت نہیں۔ بس آلو دگنے کریں اور شوربہ اپنے ماڈل کے سائز کے مطابق 1 کپ یا 1.5 کپ رکھیں۔ بہترین بغیر پانی نکالے میشڈ پوٹیٹوز کے لیے اپنے آلو کا وزن کریں! اس سے بہترین نتائج ملیں گے کیونکہ ان کا سائز بہت مختلف ہو سکتا ہے۔ اگر آپ کے پاس کچن اسکیل نہیں ہے اور آپ کو اندازے سے کام لینا ہو تو تقریباً 3 پاؤنڈ بنانے کے لیے 10 اوسط سائز کے یوکون گولڈ آلو استعمال کریں۔ اپنے ٹکڑے ایک جیسے سائز کے کاٹنے کی پوری کوشش کریں۔ یکساں پکانے کے لیے آپ نہیں چاہتے کہ کچھ ٹکڑے بہت بڑے ہوں، یا دوسرے بہت چھوٹے۔ اپنے آلوؤں کو زیادہ میش نہ کریں! ہموار ہو جائیں تو بس تیار ہیں۔ زیادہ پروسیس اور میش کرنے سے چپچپی ساخت بن سکتی ہے، اور یہ کوئی نہیں چاہتا! انہیں اضافی کریمی بنائیں۔ اضافی کریمی پن کے لیے اپنے آلو کے میش میں کاجو کی کریم یا ویگن کریم چیز کا ایک چمچ ڈال کر ہلائیں۔ بچا ہوا فریج میں 3-4 دن رہتا ہے یا ہوا بند کر کے 3 ماہ تک منجمد کیا جا سکتا ہے۔"],[]))
recs.append(R(9480093,"بغیر تیل سوکا بریڈ (چنے کی فلیٹ بریڈ)",
"سوکا فلیٹ بریڈ نرم، ذائقے دار اور ہمہ جہت ہے۔ اسے پین کیکس، پیٹا، پیزا کے آٹے کے طور پر استعمال کریں یا ٹکڑوں میں کاٹ کر اپنے پسندیدہ ڈپ میں ڈبوئیں۔",
"2 عدد 7\" فلیٹ بریڈ","1 سرونگ",
["1 کپ چنے کا آٹا یا بیسن، میں کچے چنے اپنے وائٹامکس میں پیستی ہوں","1 کپ پانی","¼ چائے کا چمچ پیاز پاؤڈر (پین کیکس کے لیے چھوڑ دیں)","¼ چائے کا چمچ لہسن پاؤڈر (پین کیکس کے لیے چھوڑ دیں)","½ چائے کا چمچ سمندری نمک (پین کیکس کے لیے چھوڑ دیں)",
("اختیاری سوکا پیزا ٹاپنگز","گھر کا بنا پیسٹو"),("اختیاری سوکا پیزا ٹاپنگز","کٹا ہوا ٹماٹر"),("اختیاری سوکا پیزا ٹاپنگز","کٹی ہوئی مرچ"),("اختیاری سوکا پیزا ٹاپنگز","کٹی ہوئی ہری پیاز"),("اختیاری سوکا پیزا ٹاپنگز","ویگن پارمیزان پنیر"),
("اختیاری سوکا پین کیک ٹاپنگز","میپل سیرپ"),("اختیاری سوکا پین کیک ٹاپنگز","تازہ بیریز"),("اختیاری سوکا پین کیک ٹاپنگز","بلو بیری چیا جیم"),("اختیاری سوکا پین کیک ٹاپنگز","بادام کا مکھن"),
("ڈبو کر کھانے کے اختیاری ڈپس","گواکامول"),("ڈبو کر کھانے کے اختیاری ڈپس","ڈل پکل ڈپ"),("ڈبو کر کھانے کے اختیاری ڈپس","کاجو کی کریم")],
["چنے کا آٹا اور مصالحے (اگر استعمال کر رہے ہیں، پین کیکس کے لیے چھوڑ دیں) ایک مکسنگ پیالے میں ملائیں۔ پھر پانی ڈال کر اچھی طرح ملائیں۔ جب آپ اپنا نان اسٹک گرڈل گرم کر رہے ہوں تو آمیزے کو 5 منٹ رکھ دیں۔",
"جب آپ کا گرڈل گرم ہو جائے تو ہر فلیٹ بریڈ کے لیے آدھا آمیزہ ڈالیں۔ آپ کو تقریباً 6-7 انچ کے دو گول ملیں گے۔ 4-5 منٹ پکائیں، یہاں تک کہ کنارے اندر تک پکے ہوئے نظر آئیں اور اوپر کئی بلبلے ہوں۔ احتیاط سے پلٹیں، پہلے کناروں کے گرد کھرچ لیں تاکہ یقینی ہو کہ چپکی ہوئی نہیں ہے۔",
"دوسری طرف مزید 3-4 منٹ، سنہری اور اندر تک پکنے تک پکائیں۔ ایک ڈش یا کٹنگ بورڈ پر منتقل کریں اور جو طریقہ آپ استعمال کر رہے ہیں اس کے مطابق مرضی سے پیش کریں۔"],
["پکانے سے پہلے آمیزے کو کم از کم 10 منٹ رکھ دیں۔ یقینی بنائیں کہ آمیزہ اوپر ڈالنے سے پہلے آپ کا گرڈل بہت گرم ہو۔ یہ بھی یقینی بنائیں کہ آپ کا گرڈل نان اسٹک ہو، ورنہ ہو سکتا ہے آپ کو اس پر چکنائی لگانی پڑے۔ ایک پرانا، بہت استعمال شدہ گرڈل آخرکار اپنی نان اسٹک طاقت کھو دے گا، اس لیے اپنی صوابدید استعمال کریں، کیونکہ آپ اپنے اوزار کو بہتر جانتے ہیں۔ اگر شک ہو تو پلیٹوں پر چکنائی لگائیں یا پہلے تھوڑے آمیزے سے ٹیسٹ کریں۔ سوکا پلٹتے وقت پہلے کناروں کے گرد کھرچیں، تاکہ یقینی ہو کہ یہ چپکی ہوئی نہیں ہے۔ پھر پلٹیں۔ اگر نمکین اختیار استعمال کر رہے ہیں تو ذائقہ بڑھانے کے لیے زیرہ، لال مرچ پاؤڈر یا کیین مرچ جیسے مزید مصالحے بلا جھجک ڈالیں۔ اگر سوکا پین کیکس بنا رہے ہیں تو درج تمام مصالحے چھوڑ دیں، اور اس کی جگہ ایک چٹکی دار چینی یا جائفل استعمال کر سکتے ہیں۔ اختیاری ٹاپنگز اور ڈپس غذائی معلومات میں شامل نہیں ہیں۔"],[]))
recs.append(R(9483756,"آم اور پالک اسموتھی [جس کا ذائقہ ہرا نہیں لگتا]",
"یہ سادہ ہری آم اور پالک اسموتھی کی ترکیب \"ذائقے\" میں ہری نہیں لگتی۔ یہ قدرتی طور پر میٹھی، بالکل لذیذ اور آپ کے لیے 'مفید' اجزا سے بھری ہوئی ہے۔",
"2 سرونگ (تقریباً 4 کپ)","1 سرونگ",
["1 تازہ کیلا","2 بڑی مٹھی بیبی پالک","1 کپ منجمد آم کے ٹکڑے","1 کپ منجمد اسٹرابیری کے ٹکڑے یا ثابت","1 کھانے کا چمچ ہموار مونگ پھلی کا مکھن","1.5 کپ بغیر میٹھا کاجو کا دودھ یا اپنی پسند کا نباتاتی دودھ"],
["تمام اجزا اپنے بلینڈر میں ڈالیں اور ہموار اور کریمی ہونے تک پروسیس کریں۔ ٹھنڈا نوش فرمائیں۔"],
["اگر آپ کے پاس تازہ کیلا موجود نہیں ہے تو آپ اس کی جگہ منجمد کیلا استعمال کر سکتے ہیں۔ اس طرح آپ کو کیلے کا ذائقہ تھوڑا کم ملے گا، لیکن پھر بھی وہ مٹھاس ملے گی جو یہ دیتا ہے۔ جب زیادہ منجمد اجزا استعمال کر رہے ہوں تو اسے ہموار کرنے کے لیے آپ کو تھوڑا اور دودھ یا کچھ پانی بھی چاہیے ہو سکتا ہے۔ دودھ کے لیے آپ کے پاس اور آپ کو پسند کوئی بھی دودھ استعمال کر سکتے ہیں۔ اسے بچوں کے لیے موزوں بنائیں۔ چونکہ ہم پہلے آنکھوں سے کھاتے ہیں، بچے ہری اسموتھی پینے کے مخالف ہو سکتے ہیں، اس لیے اس کے ساتھ تھوڑا مزہ کریں اور اسے \"ہلک اسموتھی\" یا \"نینجا ٹرٹل\" یا جو بھی ان کی پسند ہو کہہ دیں۔ 🙂 مونگ پھلی سے پاک کے لیے مونگ پھلی کے مکھن کی جگہ بادام کا مکھن یا اپنی پسند کا کوئی اور گری دار میوے کا مکھن استعمال کریں۔ اسے مکمل طور پر گری دار میوے سے پاک بنانے کے لیے مونگ پھلی کے مکھن کی جگہ سورج مکھی کا مکھن یا اپنی پسند کا کوئی اور بیجوں کا مکھن استعمال کریں، اور کاجو کے دودھ کی جگہ اوٹ، ناریل یا سویا دودھ استعمال کریں۔ جو آپ کے پاس ہے استعمال کریں! اگر آپ کے پاس پالک نہیں ہے لیکن کیل ہے تو وہ آزمائیں۔ یا اگر آپ کے پاس تازہ آم اور اسٹرابیریاں ہیں، منجمد نہیں، تو وہ استعمال کریں! اس آم اور پالک اسموتھی کو اپنی بنا لیں۔ بس اجزا کے تازہ اور منجمد کے تناسب کو ٹھیک کرتے وقت اس کے مطابق مائع بڑھانا یا گھٹانا یاد رکھیں۔"],[]))
recs.append(R(9484573,"ایئر فرائر بٹرنٹ اسکواش [دو طریقوں سے!]",
"انہیں بنانے کے دو طریقے، نمکین یا میٹھا! دونوں صورتوں میں آپ اس ایئر فرائر بٹرنٹ اسکواش سے بہت متاثر ہوں گے۔ دونوں ورژن بے حد لذیذ اور تیار کرنے میں آسان ہیں۔",
"4 سرونگ","1 سرونگ",
[("نمکین ورژن","2 پاؤنڈ بٹرنٹ اسکواش، تقریباً 4 کپ آدھے انچ کے ٹکڑوں میں کٹا ہوا"),("نمکین ورژن","2 کھانے کے چمچ کم سوڈیم سبزیوں کا شوربہ"),("نمکین ورژن","½ چائے کا چمچ سمندری نمک"),("نمکین ورژن","½ چائے کا چمچ اسموکڈ پاپریکا"),("نمکین ورژن","½ چائے کا چمچ لہسن پاؤڈر"),("نمکین ورژن","½ چائے کا چمچ لال مرچ پاؤڈر"),("نمکین ورژن","½ چائے کا چمچ پیاز پاؤڈر"),
("میٹھا ورژن","2 پاؤنڈ بٹرنٹ اسکواش، تقریباً 4 کپ آدھے انچ کے ٹکڑوں میں کٹا ہوا"),("میٹھا ورژن","2 کھانے کے چمچ میپل سیرپ"),("میٹھا ورژن","1 چائے کا چمچ دار چینی"),("میٹھا ورژن","⅛ چائے کا چمچ جائفل"),("میٹھا ورژن","⅛ چائے کا چمچ سمندری نمک")],
["اپنے بٹرنٹ اسکواش کو چھیل کر آدھے انچ کے چوکور ٹکڑوں میں کاٹیں۔ ضرورت ہو تو اوپر دی گئی مرحلہ وار تصاویر دیکھیں۔",
"کٹے ہوئے ٹکڑے ایک بڑے مکسنگ پیالے میں اس اختیار کے تمام مصالحوں کے ساتھ ڈالیں جو آپ بنا رہے ہیں۔ اچھی طرح ملائیں اور اپنے ایئر فرائر کی ٹوکری میں ایک برابر تہہ میں رکھیں۔",
"400 ڈگری F پر 15-20 منٹ پکائیں، اپنے ماڈل کے مطابق اور آدھے وقت پر اچھی طرح ہلا دیں۔ اسکواش اس وقت تیار ہے جب وہ کانٹے سے نرم اور کناروں کے گرد کرکرا ہو۔"],
["یکساں پکانے کے لیے اپنے اسکواش کو جتنا ممکن ہو ایک سائز کا کاٹیں۔ اگر آپ کچھ ٹکڑے بہت بڑے چھوڑ دیں گے تو کچھ ٹکڑے سخت رہ جائیں گے۔ انہیں بالکل کامل ہونا ضروری نہیں، لیکن انہیں جتنا ممکن ہو ایک جیسے سائز کا کاٹنے کی کوشش کریں۔ جلدی پکانے کے لیے اپنے ٹکڑے میری تجویز کردہ آدھے انچ سے بھی چھوٹے کاٹیں۔ ایئر فرائرز کی طاقت مختلف ہوتی ہے اس لیے تقریباً 15 منٹ پر دیکھنا شروع کریں۔ اسکواش اس وقت تیار ہے جب کانٹے سے نرم ہو اور کنارے بھورے اور کرکرے ہوں۔ وقت بچانے کے لیے آپ اپنے سپر مارکیٹ سے پہلے سے کٹا ہوا بٹرنٹ اسکواش خرید سکتے ہیں، لیکن پھر بھی آپ کو انہیں چھوٹے ٹکڑوں میں کاٹنا ہوگا۔ بچا ہوا فریج میں 3-4 دن رہتا ہے۔ آپ دوبارہ گرم کرنے کے لیے ایئر فرائی کر سکتے ہیں یا ٹوسٹر اوون استعمال کر سکتے ہیں۔ غذائی معلومات نمکین ورژن کے ¼ کے لیے ہیں۔ میٹھے ورژن میں فی سرونگ 131 کیلوریز ہیں۔"],[]))
recs.append(R(9490339,"ویگن ٹیکو سلاد",
"اگر آپ کچھ تازہ، تسلی بخش اور ذائقے سے بھرپور چاہتے ہیں تو یہ ویگن ٹیکو سلاد آپ کا جواب ہے!",
"4 سرونگ","1 سرونگ",
[("ٹیکو میٹ کے لیے","15 اونس کا ڈبہ چنے چھانے اور دھوئے ہوئے"),("ٹیکو میٹ کے لیے","1 کپ پیکن"),("ٹیکو میٹ کے لیے","3 کھانے کے چمچ کم سوڈیم سویا ساس یا گلوٹین فری کے لیے تماری"),("ٹیکو میٹ کے لیے","1 چائے کا چمچ پسا ہوا زیرہ"),("ٹیکو میٹ کے لیے","1 چائے کا چمچ اسموکڈ پاپریکا"),("ٹیکو میٹ کے لیے","1 چائے کا چمچ لال مرچ پاؤڈر"),("ٹیکو میٹ کے لیے","1 چائے کا چمچ لہسن پاؤڈر"),
("سلاد کے لیے","5 کپ آئس برگ لیٹش کٹی ہوئی"),("سلاد کے لیے","15 اونس کا ڈبہ کالے لوبیے چھانے اور دھوئے ہوئے"),("سلاد کے لیے","1 کپ چیری ٹماٹر آدھے کٹے ہوئے"),("سلاد کے لیے","½ کپ مکئی منجمد پگھلائی ہوئی یا ڈبہ بند"),("سلاد کے لیے","⅓ کپ لال پیاز کٹی ہوئی"),
("ڈریسنگ کے لیے (1 یا زیادہ چنیں)","سالسا"),("ڈریسنگ کے لیے (1 یا زیادہ چنیں)","ویگن کریما فریسکا"),("ڈریسنگ کے لیے (1 یا زیادہ چنیں)","گواکامول"),("ڈریسنگ کے لیے (1 یا زیادہ چنیں)","ویگن سور کریم"),
("اختیاری ٹاپنگز","ہالاپینو، ایووکاڈو کے قتلے، تازہ ہرا دھنیا، ٹورٹیلا چپس یا پٹیاں")],
["ٹیکو میٹ کے تمام اجزا اپنے فوڈ پروسیسر میں ڈالیں اور کٹنے تک پلس کریں، لیکن پھر بھی بھربھرا اور بہت ساخت کے ساتھ۔ زیادہ پروسیس نہ کریں۔ نمک اور کالی مرچ چکھیں، اور ضرورت ہو تو کچھ ڈالیں۔",
"\"میٹ\" ایک بڑے مکسنگ پیالے میں منتقل کریں اور سلاد کے باقی تمام اجزا اسی پیالے میں ڈالیں۔ اچھی طرح ملائیں۔",
"اوپر دیے گئے اختیارات میں سے سلاد ڈریسنگ چنیں، یا کوئی اور جو آپ کو پسند ہو۔ اگر آپ بچا ہوا رکھنے کا ارادہ رکھتے ہیں تو میں سفارش کرتی ہوں کہ ڈریسنگ کو سلاد میں ملانے کے بجائے ہر پیالے میں پیش کریں، تاکہ لجلجا پن روکنے کے لیے آپ انہیں الگ الگ رکھ سکیں۔"],
["ٹیکو میٹ کو زیادہ پروسیس نہ کریں۔ آپ نہیں چاہتے کہ یہ بلینڈ ہو، اس لیے بھربھرا ہونے تک پلس کریں اور بہترین نتائج کے لیے بہت ساخت برقرار رکھیں۔",
"سلاد کو لجلجا ہونے سے بچانے کے لیے سلاد اور اپنی پسند کی ڈریسنگ کو الگ الگ رکھیں۔",
"بچا ہوا فریج میں 3-4 دن رہے گا۔ غذائی معلومات میں ٹیکو میٹ اور سلاد کے اجزا شامل ہیں، ڈریسنگ یا اضافی اختیاری ٹاپنگز کے بغیر۔ ڈریسنگ کی غذائی معلومات آپ کے انتخاب کے مطابق مختلف ہوں گی۔ آپ کو وہ غذائی معلومات ہر ڈریسنگ کی ترکیب کے نیچے ملیں گی۔"],[]))
recs.append(R(9491703,"میچا انرجی بالز",
"ان ہری بغیر بیک کی میچا انرجی بالز سے اپنے دن کو توانائی دیں۔",
"20 بالز","1 سرونگ",
["1 کپ گٹھلی نکالی ہوئی کھجوریں ہلکی سی بھری ہوئی","1 کپ کچے کاجو","2 کھانے کے چمچ کدو کے بیج کا پروٹین پاؤڈر یا اپنی پسند کا پروٹین پاؤڈر یا بادام کا آٹا","1 کھانے کا چمچ میچا پاؤڈر","1 چائے کا چمچ خالص ونیلا ایکسٹریکٹ","2-4 کھانے کے چمچ پانی",
("اختیاری","¼ کپ کٹے ہوئے پستے لپیٹنے کے لیے")],
["پانی کے سوا سب کچھ اپنے فوڈ پروسیسر میں ڈالیں اور سب کچھ ٹوٹنے تک پلس کریں، پیوری بنائے بغیر۔ پھر 2 کھانے کے چمچ پانی ڈالیں اور ملنے تک پلس کریں۔",
"آمیزے کو چھوئیں، اور اگر یہ گیندوں میں بیلنے کے لیے کافی چپچپا ہے تو مزید پانی نہ ڈالیں۔ اگر یہ پھر بھی بہت خشک محسوس ہو تو ایک وقت میں ایک چائے کا چمچ اور ڈالیں جب تک آپ اسے گیندوں میں بیل نہ سکیں۔",
"آمیزے کو چھوٹی نوالے کے سائز کی گیندوں میں بیلیں، فی گیند تقریباً 1 کھانے کے چمچ کے برابر آمیزہ۔ آپ کو تقریباً 20 سرونگ ملنی چاہییں۔",
"اختیاری: اگر چاہیں تو کچھ یا تمام گیندوں کو کٹے ہوئے پستوں کے آمیزے میں لپیٹ دیں۔",
"1 گھنٹہ یا زیادہ دیر فریج میں ٹھنڈا کریں اور نوش فرمائیں۔"],
["اگر آپ کی کھجوریں بہت خشک ہیں تو انہیں اپنے فوڈ پروسیسر میں ڈالنے سے پہلے 10-15 منٹ گرم پانی میں بھگو کر چھان لیں۔ اس سے وہ نرم ہو جائیں گی اور انہیں پروسیس کرنا آسان ہو جائے گا۔",
"آمیزے کو زیادہ پروسیس نہ کریں۔ یہ میچا انرجی بالز تھوڑی ساخت کے ساتھ سب سے اچھی لگتی ہیں۔",
"چپکنے سے بچنے کے لیے گیندوں کو شکل دینے کے لیے ہلکے نم ہاتھ استعمال کریں۔ آمیزہ چپچپا ہوگا، جو معمول کی بات ہے۔"],[]))
recs.append(R(9492507,"مشروم کے ساتھ ویگن روسٹ",
"مشروم اور مسو پیسٹ کی بدولت انتہائی گوشت جیسا اور امامی ذائقوں سے بھرا، بہترین ویگن روسٹ جو آپ کے منہ میں پانی لے آئے گا۔",
"8 سرونگ","1 سرونگ",
["1 کپ سفید کینیلینی پھلیاں","227 گرام (8 اونس) کا پیکٹ کریمینی یا بیبی بیلا مشروم","¾ کپ سبزیوں کا شوربہ (نمکین، اچھی کوالٹی اور ذائقے دار شوربہ استعمال کریں)","4 جوے لہسن چھلے ہوئے","1 کھانے کا چمچ سفید مسو پیسٹ","1 کھانے کا چمچ تحینی","¼ کپ نیوٹریشنل ییسٹ","2 چائے کے چمچ پیاز پاؤڈر","1 چائے کا چمچ خشک سیج","1 چائے کا چمچ خشک تھائم","1 چائے کا چمچ کوٹا ہوا خشک روزمیری","½ چائے کا چمچ کالی مرچ","280 گرام وائٹل ویٹ گلوٹین، تقریباً 2 ¼ کپ"],
["وائٹل ویٹ گلوٹین کے سوا تمام اجزا فوڈ پروسیسر میں ڈالیں اور زیادہ تر ہموار ہونے تک پروسیس کریں۔ پھر وائٹل ویٹ گلوٹین ایک وقت میں آدھا ڈالیں اور زیادہ تر ملنے تک پلس کریں۔ (اس کا کامل ہونا ضروری نہیں۔)",
"آمیزہ صاف کٹنگ بورڈ یا کسی اور صاف سطح پر منتقل کریں۔ پھر آٹے کو ہاتھوں سے 2-3 منٹ گوندھیں۔ اسے تقریباً 4 انچ چوڑے اور 8 انچ لمبے رول کی شکل دیں۔",
"اسے پارچمنٹ پیپر میں اور پھر ایلومینیم فوائل میں مضبوطی سے لپیٹیں اور سرے مروڑ کر محفوظ کر دیں۔ (حوالے کے لیے اوپر عمل کی تصاویر دیکھیں۔) پھر نیچے سے پکانے کا صرف ایک طریقہ چنیں۔",
("انسٹنٹ پاٹ کی ہدایات","اپنے انسٹنٹ پاٹ کی تہہ میں ایک کپ پانی ڈالیں اور اوپر ٹرائیویٹ رکھیں۔ پھر اپنا لپیٹا ہوا ویگن روسٹ ٹرائیویٹ پر رکھیں۔ ڈھکن بند کریں، یقینی بنائیں کہ والو سیلنگ کی پوزیشن پر ہے، اور اسے 60 منٹ کے لیے \"اسٹیم\" پر سیٹ کریں۔ برتن کو قدرتی طور پر ریلیز ہونے دیں اور محفوظ ہونے پر کھولیں۔ (قدرتی ریلیز میں تقریباً 10-12 منٹ لگیں گے۔) اپنا روسٹ کٹنگ بورڈ پر منتقل کریں اور کاٹنے سے پہلے اسے 10 منٹ آرام کرنے دیں۔"),
("بیکنگ کی ہدایات","اوون کو 375℉/190℃ پر پہلے سے گرم کریں اور لپیٹا ہوا سیٹن روسٹ بیکنگ شیٹ پر رکھیں۔ اسے درمیانی ریک پر 45 منٹ بیک کریں۔ پھر اسے الٹ دیں اور مزید 45 منٹ بیک کریں۔ اوون سے نکالیں اور کاٹنے سے پہلے اسے 10 منٹ آرام کرنے دیں۔"),
("بھاپ دینے کی ہدایات","ایک بڑے برتن میں چند انچ پانی ابالیں اور اپنی اسٹیمر ٹوکری اندر رکھ دیں۔ یقینی بنائیں کہ ٹوکری پانی کو نہ چھو رہی ہو۔ ابلنے پر آنچ کم کر کے ہلکا ابال/ہلکی آنچ برقرار رکھیں، لپیٹا ہوا ویگن روسٹ اندر رکھیں، اور اوپر ڈھکن لگا دیں۔ 35 منٹ بھاپ دیں، پھر اسے الٹ دیں اور مزید 35-45 منٹ بھاپ دیں۔ اپنے پانی کی سطح وقتاً فوقتاً دیکھتے رہیں اور ضرورت کے مطابق گرم پانی ڈالیں۔ پک جانے پر اپنا ویگن روسٹ کٹنگ بورڈ پر منتقل کریں اور کاٹنے سے پہلے اسے 10 منٹ آرام کرنے دیں۔")],
["بالکل درست نتائج کے لیے وائٹل ویٹ گلوٹین کا وزن کریں۔ اگر آپ کو کپ سے ناپنا ہی ہے تو آٹا چمچ سے ڈال کر برابر کرنا یقینی بنائیں۔ تھیلے سے براہِ راست نہ بھریں ورنہ آپ کے پاس ضرورت سے زیادہ ہو جائے گا۔",
"بہت ذائقے دار اور نمکین شوربہ استعمال کرنا یقینی بنائیں کیونکہ کوئی اور نمک نہیں ڈالا گیا۔ اگر آپ کے پاس صرف کم سوڈیم شوربہ موجود ہے تو ½-1 چائے کا چمچ نمک ڈالیں۔",
"پکنے کی جانچ کے لیے: فوائل کو آہستہ سے ہٹائیں، سیٹن روسٹ ہموار نظر آنا چاہیے۔ سختی جانچنے کے لیے اسے اپنی انگلی یا چمٹے سے دبا کر دیکھیں۔ (احتیاط، یہ گرم ہوگا!) یہ سخت محسوس ہونا چاہیے لیکن دباؤ پر تھوڑا دبے۔ ٹھنڈا ہونے پر یہ مزید سخت ہوتا رہے گا۔",
"بچا ہوا فریج میں 5 دن تک رہے گا۔ یا ویگن روسٹ کو ہوا بند فریزر کے لیے موزوں ڈبے میں 3 ماہ تک منجمد کریں۔ آپ اسے ثابت یا قتلوں میں منجمد کر سکتے ہیں۔"],[]))
